fun knownDestinationTimezone(query: String): String? {
    val text = query.lowercase(java.util.Locale.ROOT).filterNot { it.isWhitespace() }
    destinationTimezone(text)?.let { return it }
    val parts = text.split(Regex("[、,，;；/|·]"))
    if (parts.size < 2) return null
    val first = destinationTimezone(parts.first()) ?: return null
    return first.takeIf { parts.all { destinationTimezone(it) == first } }
}

private fun destinationTimezone(text: String): String? {
    destinationTimezoneAliases[text]?.let { return it }
    if (text.startsWith("中国") && text.length > 2) return destinationTimezone(text.drop(2))
    if (text.endsWith("市") || text.endsWith("省")) return destinationTimezoneAliases[text.dropLast(1)]
    return null
}
